    order = shop.orders.handle_create(
        {"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 2}, {"sku": "BOOK", "quantity": 1}]}
    ).body
    resp = shop.fulfilment.handle_packing_slip(order["order_id"])
    assert resp.status == 200
    assert resp.body == {
        "order_id": order["order_id"],
        "customer_name": "Ada",
        "lines": [{"sku": "PEN", "name": "Pen", "quantity": 2},
                  {"sku": "BOOK", "name": "Book", "quantity": 1}],
    }


def test_packing_slip_unknown_order(shop):
    resp = shop.fulfilment.handle_packing_slip("nope")
    assert (resp.status, resp.body) == (404, {"error": "order not found"})


def test_packing_slip_cancelled_order(shop):
    order = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 1}]}).body
    shop.orders.handle_cancel(order["order_id"])
    resp = shop.fulfilment.handle_packing_slip(order["order_id"])
    assert resp.status == 409
    assert "error" in resp.body

